 "claims": [
  {
   "claim": "Marco's charger is in his hands (plugged into the laptop on his lap) during core work hours",
   "target": "charger_marco",
   "expect": "ON_PERSON",
   "days": "weekday",
   "from": 10,
   "to": 16
  },
